package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class BossProgressionChecks {
 private GameWorld boss(int stage){GameWorld w=new GameWorld();w.stage=stage;w.mapIndex=4;w.stageComplete=true;w.advanceStage();w.bossActive=true;w.boss.timer=0;w.x=300;w.invulnerable=100;return w;}
 private void resolve(GameWorld w){while(w.choosingSkill())w.skipLearning();}
 private void ticks(GameWorld w,int n){for(int i=0;i<n;i++)w.step(1f/60,0,false,false);}
 @Test public void eachBossUsesAllThreePatternsAndItsOwnEffects(){for(int stage=1;stage<=3;stage++){GameWorld w=boss(stage);boolean[] seen=new boolean[3];boolean jumped=false,poison=false,fire=false,shock=false,pillar=false,heat=false;for(int i=0;i<1500;i++){w.y=500;w.vy=0;w.step(1f/60,0,false,false);if(w.boss.phase==GameWorld.Phase.ATTACK)seen[w.boss.pattern]=true;jumped|=w.boss.y>GameWorld.FLOOR+30;for(GameWorld.Shot s:w.shots){poison|=s.element==GameWorld.Element.POISON;fire|=s.element==GameWorld.Element.FIRE;}for(GameWorld.BossHazard h:w.bossHazards){shock|=h.type==GameWorld.BossHazardType.SHOCKWAVE;poison|=h.type==GameWorld.BossHazardType.POISON_POOL;pillar|=h.type==GameWorld.BossHazardType.FIRE_PILLAR;heat|=h.type==GameWorld.BossHazardType.HEAT_WAVE;}}assertArrayEquals(new boolean[]{true,true,true},seen);if(stage==1){assertTrue(jumped&&shock);assertFalse(fire||poison);}if(stage==2){assertTrue(poison);assertFalse(fire||pillar||heat);}if(stage==3){assertTrue(fire&&pillar&&heat);assertFalse(poison);}}}
 @Test public void hazardWarningAndPauseDoNotDealDamage(){GameWorld w=boss(2);w.boss.timer=1000;w.invulnerable=0;GameWorld.BossHazard h=new GameWorld.BossHazard(GameWorld.BossHazardType.POISON_POOL,w.x,112,90,30,.5f,.8f,0,1);w.bossHazards.add(h);w.paused=true;ticks(w,100);assertEquals(.5f,h.warning,0);assertEquals(6,w.hp);w.paused=false;ticks(w,28);assertEquals(6,w.hp);ticks(w,8);assertEquals(5,w.hp);}
 @Test public void shockwaveCanBeJumped(){GameWorld w=boss(1);w.boss.timer=1000;w.x=100;w.invulnerable=0;w.step(1f/60,0,false,false);w.bossHazards.add(new GameWorld.BossHazard(GameWorld.BossHazardType.SHOCKWAVE,250,112,55,28,0,2,-300,2));w.step(1f/60,0,true,false);ticks(w,65);assertEquals(6,w.hp);}
 @Test public void halfHpBossHasStrongerVolleyAndKeepsWarnings(){GameWorld w=boss(3);w.boss.hp=w.boss.maxHp/2-1;ticks(w,52);assertEquals(GameWorld.Phase.ATTACK,w.boss.phase);assertEquals(7,w.shots.size());}
 @Test public void candyGivesPermanentLevelLeadWithoutEnemyGrowthOrXpPenalty(){GameWorld w=new GameWorld();int enemy=w.enemyLevel(),hp=w.enemies.get(0).maxHp,cost=w.xpRequired(),attack=w.attackDamage();for(int i=0;i<10;i++)w.collectItem(GameWorld.Item.CANDY);assertEquals(11,w.level);assertEquals(10,w.candyLevelBonus());assertEquals(enemy,w.enemyLevel());assertEquals(hp,w.enemies.get(0).maxHp);assertEquals(cost,w.xpRequired());assertTrue(w.attackDamage()>attack);resolve(w);w.addExperience(w.xpRequired());assertEquals(12,w.level);assertEquals(2,w.enemyLevel());for(GameWorld.Enemy e:w.enemies)assertEquals(2,e.level);assertEquals(10,w.candyLevelBonus());}
 @Test public void candyLeadSurvivesMapsAndRetryButRestartClearsIt(){GameWorld w=new GameWorld();w.collectItem(GameWorld.Item.CANDY);w.collectItem(GameWorld.Item.CANDY);resolve(w);w.stageComplete=true;assertTrue(w.advanceStage());w.collectItem(GameWorld.Item.CANDY);assertEquals(3,w.candyLevelBonus());w.hp=0;assertTrue(w.retryStage());assertEquals(2,w.candyLevelBonus());assertEquals(3,w.level);assertEquals(1,w.enemyLevel());w.restart();assertEquals(0,w.candyLevelBonus());assertEquals(1,w.enemyLevel());}
 @Test public void xpCurveReachesLevelSixWithThreeHundredXp(){GameWorld w=new GameWorld();w.addExperience(300);assertEquals(6,w.level);assertEquals(0,w.xp);assertEquals(90,w.xpRequired());}
 @Test public void newRoomsClearBossHazards(){GameWorld w=boss(2);w.bossHazards.add(new GameWorld.BossHazard(GameWorld.BossHazardType.POISON_POOL,300,112,90,24,0,3,0,1));w.boss.hp=0;w.stageComplete=true;assertTrue(w.advanceStage());assertTrue(w.bossHazards.isEmpty());}
}
